49: static inline float black_scholes_value(float S, float X, float T, float r, float v) {
50:     float d1 = (logf(S / X) + (r + v * v * .5f) * T) / (v * sqrtf(T));
51:     float d2 = d1 - v * sqrtf(T);
52: 
53:     return S * CND(d1) - X * expf(-r * T) * CND(d2);
54: }
