43:     double m = std::frexp(static_cast<double>(x), &exponent);
44:     if (m < 0.70710678118654752440) {
45:         m *= 2.0;
46:         --exponent;
47:     }
48: 
49:     double z = (m - 1.0) / (m + 1.0);
50:     double z2 = z * z;
51:     double p = 1.0 / 23.0;
52:     p = 1.0 / 21.0 + z2 * p;
53:     p = 1.0 / 19.0 + z2 * p;
54:     p = 1.0 / 17.0 + z2 * p;
