35:         float x2 = X * X;
36:         float num = 1.0f + x2 * (0.0363247863f + x2 * 0.0037596663f);
37:         float den = 1.0f + x2 * (0.2029914530f + x2 * 0.0125915751f);
38:         return 0.5f + (0.39894228040f * X) * (num / den);
39:     }
40: 
41:     float k = 1.f / (1.f + 0.2316419f * L);
42:     float k2 = k * k;
43:     float k3 = k2 * k;
44:     float k4 = k2 * k2;
45:     float k5 = k3 * k2;
46: 
47:     const float invSqrt2Pi = 0.39894228040f;
48:     float w = (0.31938153f * k - 0.356563782f * k2 + 1.781477937f * k3 + -1.821255978f * k4 + 1.330274429f * k5);
49:     w *= invSqrt2Pi * expf(-L * L * .5f);
50: 
51:     if (X > 0.f)
52:         w = 1.f - w;
53:     return w;
54: }
