48: void black_scholes_serial(float Sa[], float Xa[], float Ta[], float ra[], float va[], float result[], int count) {
49:     for (int i = 0; i < count; ++i) {
50:         float S = Sa[i], X = Xa[i];
51:         float T = Ta[i], r = ra[i];
52:         float v = va[i];
53: 
54:         float d1 = (logf(S / X) + (r + v * v * .5f) * T) / (v * sqrtf(T));
55:         float d2 = d1 - v * sqrtf(T);
56: 
57:         result[i] = S * CND(d1) - X * expf(-r * T) * CND(d2);
58:     }
59: }
