65:         float S = Sa[i], X = Xa[i];
66:         float T = Ta[i], r = ra[i];
67:         float v = va[i];
68: 
69:         float dt = T / BINOMIAL_NUM;
70:         float u = expf(v * sqrtf(dt));
71:         float d = 1.f / u;
72:         float disc = expf(r * dt);
73:         float Pu = (disc - d) / (u - d);
74: 
75:         for (int j = 0; j < BINOMIAL_NUM; ++j) {
76:             float upow = powf(u, (float)(2 * j - BINOMIAL_NUM));
77:             V[j] = std::max(0.f, X - S * upow);
78:         }
79: 
80:         for (int j = BINOMIAL_NUM - 1; j >= 0; --j)
81:             for (int k = 0; k < j; ++k)
82:                 V[k] = ((1 - Pu) * V[k] + Pu * V[k + 1]) / disc;
83: 
84:         result[i] = V[0];
85:     }
86: }
