33:     const float L = fabsf(X);
34: 
35:     // Padé approximation to the integrated Gaussian series near the origin.
36:     // Use the signed argument directly to preserve CND(-X) = 1 - CND(X).
37:     if (L < 1.125f) {
38:         const float y = X * X;
39:         const float numerator = 1.0f + y * (0.0363247863f + y * 0.0037596663f);
40:         const float denominator = 1.0f + y * (0.2029914530f + y * 0.0125915751f);
41:         return 0.5f + (invSqrt2Pi * X) * (numerator / denominator);
42:     }
43: 
44:     // Retain the exponential tail approximation, evaluated in Horner form.
45:     const float k = 1.0f / (1.0f + 0.2316419f * L);
46:     float w = ((((1.330274429f * k - 1.821255978f) * k + 1.781477937f) * k - 0.356563782f) * k + 0.31938153f) * k;
47:     w *= invSqrt2Pi * expf(-L * L * 0.5f);
48: 
49:     if (X > 0.0f)
50:         w = 1.0f - w;
51:     return w;
52: }
