31: static inline float CND(float X) {
32:     float L = fabsf(X);
33: 
34:     float k = 1.f / (1.f + 0.2316419f * L);
35:     float k2 = k * k;
36:     float k3 = k2 * k;
37:     float k4 = k2 * k2;
38:     float k5 = k3 * k2;
