75:         float dt = T / BINOMIAL_NUM;
76:         float u = expf(v * sqrtf(dt));
77:         float d = 1.f / u;
78:         float disc = expf(r * dt);
79:         float Pu = (disc - d) / (u - d);
80: 
81:         for (int j = 0; j < BINOMIAL_NUM; ++j) {
82:             float upow = powf(u, (float)(2 * j - BINOMIAL_NUM));
83:             V[j] = std::max(0.f, X - S * upow);
84:         }
