34: // Cumulative normal distribution function
35: static inline float CND(float X) {
36:     const float invSqrt2Pi = 0.39894228040f;
37:     const float L = fabsf(X);
38: 
39:     // Signed [2/2] Padé approximation in the central region.
40:     if (L < 1.25f) {
41:         const float x2 = X * X;
42:         const float numerator = 1.f + x2 * (0.0363247863247863f + 0.0037596662601758f * x2);
43:         const float denominator = 1.f + x2 * (0.202991452991453f + 0.0125915750915751f * x2);
44:         return 0.5f + invSqrt2Pi * (X * (numerator / denominator));
45:     }
46: 
47:     // Keep the exponential tail, evaluating its polynomial in Horner form.
48:     float k = 1.f / (1.f + 0.2316419f * L);
49:     float w = k * (0.31938153f + k * (-0.356563782f + k * (1.781477937f + k * (-1.821255978f + k * 1.330274429f))));
50:     w *= invSqrt2Pi * expf(-L * L * .5f);
51: 
52:     if (X > 0.f)
53:         w = 1.f - w;
54:     return w;
55: }
