31: static inline float CND(float X) {
32:     const float invSqrt2Pi = 0.39894228040f;
33:     float L = fabsf(X);
34: 
35:     if (L < 0.875f) {
36:         float z = X * X;
37:         float p = 1.0f / 599040.0f;
38:         p = p * z - 1.0f / 42240.0f;
39:         p = p * z + 1.0f / 3456.0f;
40:         p = p * z - 1.0f / 336.0f;
41:         p = p * z + 1.0f / 40.0f;
42:         p = p * z - 1.0f / 6.0f;
43:         p = p * z + 1.0f;
44:         return 0.5f + (invSqrt2Pi * X) * p;
45:     }
46: 
47:     float k = 1.f / (1.f + 0.2316419f * L);
48:     float k2 = k * k;
49:     float k3 = k2 * k;
50:     float k4 = k2 * k2;
51:     float k5 = k3 * k2;
52: 
53:     float w = (0.31938153f * k - 0.356563782f * k2 + 1.781477937f * k3 + -1.821255978f * k4 + 1.330274429f * k5);
54:     w *= invSqrt2Pi * expf(-L * L * .5f);
55: 
56:     if (X > 0.f)
57:         w = 1.f - w;
58:     return w;
59: }
