47: void black_scholes_serial(float Sa[], float Xa[], float Ta[], float ra[], float va[], float result[], int count) {
48:     for (int i = 0; i < count; ++i) {
49:         float S = Sa[i], X = Xa[i];
50:         float T = Ta[i], r = ra[i];
51:         float v = va[i];
52: 
53:         float d1 = (logf(S / X) + (r + v * v * .5f) * T) / (v * sqrtf(T));
54:         float d2 = d1 - v * sqrtf(T);
55: 
56:         result[i] = S * CND(d1) - X * expf(-r * T) * CND(d2);
57:     }
58: }
