63:     for (int i = 0; i < count; ++i) {
64:         float S = Sa[i], X = Xa[i];
65:         float T = Ta[i], r = ra[i];
66:         float v = va[i];
67: 
68:         float dt = T / BINOMIAL_NUM;
69:         float u = expf(v * sqrtf(dt));
70:         float d = 1.f / u;
71:         float disc = expf(r * dt);
72:         float Pu = (disc - d) / (u - d);
73: 
74:         for (int j = 0; j < BINOMIAL_NUM; ++j) {
75:             float upow = powf(u, (float)(2 * j - BINOMIAL_NUM));
76:             V[j] = std::max(0.f, X - S * upow);
77:         }
78: 
79:         for (int j = BINOMIAL_NUM - 1; j >= 0; --j)
80:             for (int k = 0; k < j; ++k)
81:                 V[k] = ((1 - Pu) * V[k] + Pu * V[k + 1]) / disc;
82: 
83:         result[i] = V[0];
84:     }
85: }
