39:     // Signed [2/2] Padé approximation in the central region.
40:     if (L < 1.25f) {
41:         const float x2 = X * X;
42:         const float numerator = 1.f + x2 * (0.0363247863247863f + 0.0037596662601758f * x2);
43:         const float denominator = 1.f + x2 * (0.202991452991453f + 0.0125915750915751f * x2);
44:         return 0.5f + invSqrt2Pi * (X * (numerator / denominator));
45:     }
